#include <iostream>
#include <stack>
#include <queue>
#include <deque>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
string s; cin >> s; stack<char> st; bool ok = true; for (char c : s) { if (c == '(' || c == '[' || c == '{') st.push(c); else { if (st.empty()) { ok = false; break; } char t = st.top(); st.pop(); if ((c == ')' && t != '(') || (c == ']' && t != '[') || (c == '}' && t != '{')) ok = false; } } if (!st.empty()) ok = false; cout << (ok ? "YES" : "NO") << "\n";
    return 0;
}

