#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
int n; cin >> n; vector<long long> h(n); for (auto& x : h) cin >> x; int l = 0, r = n - 1; long long best = 0; while (l < r) { best = max(best, min(h[l], h[r]) * (r - l)); if (h[l] < h[r]) l++; else r--; } cout << best << "\n";
    return 0;
}
